local SHOP={}
for b,p in pairs(PROFILES) do
 ROWS[b]=p.seats SHOP[b]=p.shop
 if p.door then SnrDoors[b]=p.door end
 if p.floor_polys and not SnrPolys[b] then SnrPolys[b]=p.floor_polys end
end
-- 6.0 (11-03): the merchant stays where his walk in stops (the door point) instead of turning off to the shop spot
for b,p in pairs(PROFILES) do if p.shop and p.door then p.shop={p.door[1],p.door[2],p.shop[3]} SHOP[b]=p.shop end end
function koWujeHallExit(b) local p=PROFILES[b] return p and p.exit end
function koWujeHallHost(b)
 local p=PROFILES[b]
 if p then for _,s in ipairs(p.seats) do if s[4]==0 then return s end end end
end
function koWujeHallCatalog()
 local list={}
 for b,p in pairs(PROFILES) do if p.side_capacity==20 then list[#list+1]={b,p.label or tostring(b)} end end
 table.sort(list,function(a,z) return a[1]<z[1] end)
 return list
end
local MIN=7.99 -- (dx)^2 + (2*dy)^2; adjacent canonical diagonal seats are 8 apart.
local ref=nil
local intent={}
local reserved=nil
local laidOutCount=nil
local visitors={}
local rowsBack=nil
local held={} -- ko QA 11-04: seat kept for someone still walking in from the door
local function context()
 if ref~=JY.Smap then ref=JY.Smap intent={} reserved=nil laidOutCount=nil visitors={} held={} if rowsBack then ROWS[rowsBack[1]]=rowsBack[2] rowsBack=nil end end
end
local function bg() return SnrBg() end
local function isCity()
 local b=bg()
 if rawget(_G,"koWujeTownNPC") then return false end
 return b and b>0 and ROWS[b] and JY.Status~=GAME_WMAP and JY.Status~=GAME_WARWIN and JY.Status~=GAME_WARLOSE
end
local function dist(x,y,a,b) return (x-a)^2+4*(y-b)^2 end
local function free(x,y,occupied)
 for _,p in ipairs(occupied) do if dist(x,y,p[1],p[2])<MIN then return false end end
 return true
end
local function floorOK(b,x,y)
 if x<1 or x>33 or y<3 or y>21 then return false end
 local key=x..","..y
 if SnrKeep[b] and SnrKeep[b][key] then return true end
 if SnrBlock[b] and SnrBlock[b][key] then return false end
 local px,py=11+18*x,3+18*y
 for _,poly in ipairs(SnrPolys[b] or {}) do
  local inside=false local n=#poly/2 local j=n
  for i=1,n do
   local ax,ay,bx,by=poly[2*i-1],poly[2*i],poly[2*j-1],poly[2*j]
   if (ay>py)~=(by>py) and px<(bx-ax)*(py-ay)/(by-ay)+ax then inside=not inside end
   j=i
  end
  if inside then return false end
 end
 return true
end
local function floorSpot(b,x,y,occupied)
 local best,bx,by
 for yy=3,21 do for xx=1,33 do
  if floorOK(b,xx,yy) and free(xx,yy,occupied) then
   local cost=dist(x,y,xx,yy)
   if not best or cost<best then best,bx,by=cost,xx,yy end
  end
 end end
 return bx or x,by or y
end
local function occupied(exclude)
 local result={}
 for _,u in ipairs(JY.Smap) do
  if not exclude[u[1]] and not held[u[1]] then result[#result+1]={u[2],u[3]} end
 end
 for k,h in pairs(held) do if not exclude[k] then result[#result+1]={h[1],h[2]} end end
 return result
end
local function plan(points,b,used,initial)
 local result={}
 local profile=PROFILES[b]
 for i,p in ipairs(points) do
  local v=visitors[p[1]]
  if v then result[i]={v[1],v[2],v[3]} used[#used+1]={v[1],v[2]} end
 end
 local service=profile.shop
 if profile.shop_large then
  local ids={} local count=0
  for _,u in ipairs(JY.Smap) do if u[1]~=375 and not ids[u[1]] then ids[u[1]]=true count=count+1 end end
  for _,u in ipairs(points) do if u[1]~=375 and not ids[u[1]] then ids[u[1]]=true count=count+1 end end
  if count>=21 then service=profile.shop_large end
 end
 SHOP[b]=service
 for i,p in ipairs(points) do
  if p[1]==375 and service then
   result[i]={service[1],service[2],service[3]}
  end
 end
 -- Keep the service position vacant before the merchant's arrival, too.
 if service and free(service[1],service[2],used) then used[#used+1]={service[1],service[2]} end
 local seats=ROWS[b]
 local host,hs,best
 if initial then
  for i,p in ipairs(points) do if not result[i] then
   for j,seat in ipairs(seats) do if seat[4]==0 and free(seat[1],seat[2],used) then
    local cost=dist(p[2],p[3],seat[1],seat[2])
    if not best or cost<best or (cost==best and p[1]<points[host][1]) then host,hs,best=i,j,cost end
   end end
  end end
  if host then
   local seat=seats[hs]
   result[host]={seat[1],seat[2],seat[3]} used[#used+1]={seat[1],seat[2]}
  end
 end
 local order={}
 for i,p in ipairs(points) do if not result[i] then order[#order+1]=i end end
 table.sort(order,function(a,z) return points[a][1]<points[z][1] end)
 local sparse=initial and PROFILES[b].sparse
 -- 6.0 (11-03): one person alone gets sparse[1] (the report spot, where a messenger stands) only when he is a messenger;
 -- anyone else takes the usual seats in order
 if sparse and #order==1 then local who=JY.Person[points[order[1]][1]] if not (who and ({["\129\073\129\101"]=true,["\133\090\129\101"]=true,["\130\114\133\120"]=true,["\130\084\130\114"]=true,["\130\066\130\089"]=true,["\130\126\130\114"]=true})[who["\208\213\195\251"]]) then sparse=nil end end
 if sparse and sparse[#order] then seats=sparse[#order] end
 for _,i in ipairs(order) do
  local p=points[i]
  for _,seat in ipairs(seats) do
   if seat[4]~=0 and free(seat[1],seat[2],used) then
    result[i]={seat[1],seat[2],seat[3]} used[#used+1]={seat[1],seat[2]} break
   end
  end
  if not result[i] then
   local x,y=floorSpot(b,p[2],p[3],used)
   result[i]={x,y,p[4]} used[#used+1]={x,y}
  end
 end
 return result
end
local function current(pid)
 for _,u in ipairs(JY.Smap) do if u[1]==pid then return u end end
end
local function removeDuplicates()
 local seen={}
 for i=#JY.Smap,1,-1 do
  local u=JY.Smap[i]
  if seen[u[1]] then table.remove(JY.Smap,i) else seen[u[1]]=true end
 end
end
local function normalize(force)
 context()
 if not isCity() then return end
 removeDuplicates()
 local changed=force or JY.Base["\202\194\188\2541987"]~=10
 for i,u in ipairs(JY.Smap) do
  for j=1,i-1 do local v=JY.Smap[j] if dist(u[2],u[3],v[2],v[3])<MIN then changed=true end end
 end
 if not changed then return end
 local points={}
 for _,u in ipairs(JY.Smap) do
  local p=intent[u[1]] or {u[2],u[3],u[4]}
  points[#points+1]={u[1],p[1],p[2],p[3]}
 end
 local slots=plan(points,bg(),{},true)
 for i,u in ipairs(JY.Smap) do local s=slots[i] u[2]=s[1] u[3]=s[2] u[4]=s[3] end
 JY.Base["\202\194\188\2541987"]=10
 laidOutCount=#JY.Smap
end
rawset(_G,"koWujeCityRepair",normalize)

-- The native save struct stores integer scene coordinates. Keep fractional seats
-- and reporting visitors in the campaign companion instead of rounding the ranks.
function koWujeCityState()
 context()
 return {version=10,room=bg(),intent=intent,visitors=visitors}
end
function koWujeCityRestore(state)
 context()
 if not isCity() or type(state)~="table" or state.version~=10 or state.room~=bg() then return false end
 intent=state.intent or {} visitors=state.visitors or {}
 laidOutCount=#JY.Smap
 return true
end

-- Every initial group is assigned together immediately before its backdrop is shown.
local koDrawn=nil
local setScene=SetSceneID
function SetSceneID(id,...)
 koDrawn=nil
 if ROWS[id] then SnrRoom=id normalize(true) end
 return setScene(id,...)
end
local add=AddPerson
function AddPerson(pid,x,y,d)
 context()
 if isCity() then
  local old=current(pid)
  if old then old[2]=x old[3]=y old[4]=d old[5]=0 return end
  if x>=1 and x<=33 and y>=3 and y<=21 then
   local s=reserved and reserved[pid]
   if not s then s=plan({{pid,x,y,d}},bg(),occupied({}),false)[1] end
   x,y,d=s[1],s[2],s[3]
  end
 end
 return add(pid,x,y,d)
end
local snrAdd=SnrAdd
function SnrAdd(pid,x,y,d,exact)
 context()
 if isCity() then intent[pid]={x,y,d} end
 return snrAdd(pid,x,y,d,exact)
end
local fix=SnrFixSpot
function SnrFixSpot(pid,x,y,noseat)
 context()
 if not isCity() then return fix(pid,x,y,noseat) end
 if reserved and reserved[pid] then return reserved[pid][1],reserved[pid][2] end
 if visitors[pid] then return visitors[pid][1],visitors[pid][2] end
 local used=occupied({[pid]=true})
 if noseat then
  if floorOK(bg(),x,y) and free(x,y,used) then return x,y end
  return floorSpot(bg(),x,y,used)
 end
 local slots=plan({{pid,x,y,0}},bg(),used,false)
 return slots[1][1],slots[1][2]
end

-- Scripted reporting groups use a two-column formation in the central audience area.
local function reportSlots(list,b,used)
 if not PROFILES[b].report_center or #list<2 or #list>6 then return nil end
 for _,p in ipairs(list) do if p[1]==375 then return nil end end
 local center=PROFILES[b].report_center or PROFILES[b].shop_large or PROFILES[b].shop
 if #JY.Smap+#list>=21 then used[#used+1]={center[1],center[2]} end
 local shifts={}
 for y=-5,5 do for x=-5,5 do shifts[#shifts+1]={x,y,x*x+4*y*y} end end
 table.sort(shifts,function(a,z) if a[3]~=z[3] then return a[3]<z[3] end if a[2]~=z[2] then return a[2]<z[2] end return a[1]<z[1] end)
 for _,shift in ipairs(shifts) do
  for _,step in ipairs({2,2.5,3,3.5,4}) do
   local slots,occupiedNow={},{}
   for _,v in ipairs(used) do occupiedNow[#occupiedNow+1]=v end
   local valid=true
   for i,p in ipairs(list) do
    local col=(i-1)%2-.5
    local row=math.floor((i-1)/2)-(math.ceil(#list/2)-1)/2
    local face=center[3] or 0
    local forward=({[0]={2,-1},[1]={-2,1},[2]={-2,-1},[3]={2,1}})[face]
    local lateral=face<2 and {2,1} or {2,-1}
    local x=center[1]+shift[1]+(col*lateral[1]-row*forward[1])*step/2
    local y=center[2]+shift[2]+(col*lateral[2]-row*forward[2])*step/2
    if not floorOK(b,x,y) or not free(x,y,occupiedNow) then valid=false break end
    slots[i]={x,y,center[3] or 0} occupiedNow[#occupiedNow+1]={x,y}
   end
   if valid then return slots end
  end
 end
end
-- Arrival groups reserve all destinations first; subsequent actors cannot claim the same seat.
-- ko QA 11-05: the report group re-forms walking together
local function koBestSlots(all,slots)
 if #all<2 or #all>6 then return slots end
 local D=rawget(_G,"SnrDoors") D=D and D[bg()]
 local pos={}
 for i,p in ipairs(all) do
  local w=current(p[1])
  if w then pos[i]={w[2],w[3]} elseif D then pos[i]={D[1],D[2]} else pos[i]={slots[i][1],slots[i][2]} end
 end
 local best,bc,used,cur={},nil,{},{}
 local function go(i,c)
  if bc and c>=bc then return end
  if i>#all then bc=c for k=1,#all do best[k]=cur[k] end return end
  for j=1,#slots do if not used[j] then
   used[j]=true cur[i]=j
   go(i+1,c+(slots[j][1]-pos[i][1])^2+4*(slots[j][2]-pos[i][2])^2)
   used[j]=false
  end end
 end
 go(1,0)
 local r={} for k=1,#all do r[k]=slots[best[k]] end
 return r
end
local function koMoveTogether(T)
 local plans,rounds={},0
 for i,t in ipairs(T) do
  local w=current(t[1])
  if w and (w[2]-t[2][1])^2+(w[3]-t[2][2])^2>0.01 then
   local L=SnrPlan(w[2],w[3],t[2][1],t[2][2],t[1])
   plans[i]=L or {}
   if #plans[i]>rounds then rounds=#plans[i] end
   -- Preserve the exact fractional starting point of the calculated route.
  else plans[i]={} end
 end
 for k=1,rounds do
  local args={}
  for i,t in ipairs(T) do local leg=plans[i][k]
   if leg then args[#args+1]=t[1] args[#args+1]=leg[1] args[#args+1]=leg[2] end
  end
  if #args>0 then MovePerson(table.unpack(args)) end
 end
 for _,t in ipairs(T) do
  local w=current(t[1]) if w and not (rawget(_G,"koRouteFailed") and koRouteFailed(t[1])) then w[2],w[3],w[4]=t[2][1],t[2][2],t[2][3] w[5]=0 end
 end
 DrawSMap() ShowScreen()
end
local enterMany=SnrEnterMany
function SnrEnterMany(list,ax,ay)
 context()
 if not isCity() then return enterMany(list,ax,ay) end
 local skip={} for _,p in ipairs(list) do skip[p[1]]=true intent[p[1]]={p[2],p[3],p[4]} end
 -- ko QA 11-04: join the reporters already standing here and re-form everyone in two columns
 local early={}
 if #list>=2 then for _,u in ipairs(JY.Smap) do if visitors[u[1]] and not skip[u[1]] then early[#early+1]={u[1],u[2],u[3],u[4]} end end end
 local all,skipAll={},{}
 for k in pairs(skip) do skipAll[k]=true end
 for _,p in ipairs(early) do all[#all+1]=p skipAll[p[1]]=true end
 for _,p in ipairs(list) do all[#all+1]=p end
 local hostHere=false
 for _,s in ipairs(ROWS[bg()]) do if s[4]==0 then for _,u in ipairs(JY.Smap) do
  if not skip[u[1]] and math.abs(u[2]-s[1])<.01 and math.abs(u[3]-s[2])<.01 then hostHere=true end
 end end end
 local slots=hostHere and reportSlots(all,bg(),occupied(skipAll))
 if slots then
  slots=koBestSlots(all,slots)
  for i,p in ipairs(all) do visitors[p[1]]=slots[i] end
  local T={}
  for i,p in ipairs(early) do T[#T+1]={p[1],slots[i]} end
  koMoveTogether(T)
  local rest={} for i=#early+1,#all do rest[#rest+1]=slots[i] end
  slots=rest
 else slots=plan(list,bg(),occupied(skip),not hostHere) end
 local prepared={} reserved={}
 for i,p in ipairs(list) do
  local s=slots[i] reserved[p[1]]=s
  prepared[i]={p[1],s[1],s[2],s[3]}
 end
 local ok,e=pcall(enterMany,prepared,ax,ay)
 reserved=nil
 if not ok then error(e,0) end
end
local enter=SnrEnter
function SnrEnter(pid,x,y,d)
 context()
 if not isCity() then return enter(pid,x,y,d) end
 intent[pid]={x,y,d}
 local s=plan({{pid,x,y,d}},bg(),occupied({[pid]=true}),false)[1]
 local previous=reserved
 reserved={[pid]=s}
 local ok,e=pcall(enter,pid,s[1],s[2],s[3])
 reserved=previous
 if not ok then error(e,0) end
end
-- ko QA 11-04: 장면 도중 입장. 화면 밖에서 문턱까지 걸어와 서고, 좌석은 잡아 둔다 (뒤의 SnrMoveTo 가 자리로 데려간다)
function SnrArrive(pid,x,y,d,nohold)
 context()
 local D=rawget(_G,"SnrDoors") D=D and D[bg()]
 if not isCity() or current(pid) or not D then return SnrAdd(pid,x,y,d) end
 local s=plan({{pid,x,y,d}},bg(),occupied({[pid]=true}),false)[1]
 intent[pid]={x,y,d}
 if not nohold then held[pid]={s[1],s[2],s[3]} end
 -- 문턱이 차 있으면 문 바깥쪽으로 물러선다
 local sx,sy=D[3],D[4]
 local stand={}
 for _,u in ipairs(JY.Smap) do stand[#stand+1]={u[2],u[3]} end
 local vx,vy=(D[3]-D[1])/5,(D[4]-D[2])/5
 for k=0,4 do
  local tx,ty=D[1]+vx*k,D[2]+vy*k
  if free(tx,ty,stand) then sx,sy=tx,ty break end
 end
 add(pid,D[3],D[4],0)
 local sd
 for dd=0,3 do if CC.DX[dd]*(sx-D[3])>0 and CC.DY[dd]*(sy-D[4])>0 then sd=dd end end
 local who=current(pid)
 if sd then
  MovePerson(pid,math.abs(sx-D[3])/2,sd)
  who=current(pid)
 end
 if who and not (rawget(_G,"koRouteFailed") and koRouteFailed(pid)) then who[2]=sx who[3]=sy who[4]=sd or who[4] end
 DrawSMap() ShowScreen()
end
local move=SnrMoveTo
function SnrMoveTo(pid,x,y,d,exact)
 context()
 if isCity() then
  if visitors[pid] then local v=visitors[pid] return move(pid,v[1],v[2],d or v[3],true) end
  if pid==375 and SHOP[bg()] then local s=SHOP[bg()] x,y,d=s[1],s[2],s[3] end
  local old=intent[pid];local who=current(pid)
  local h=held[pid]
  if h then
   held[pid]=nil
   if old and old[1]==x and old[2]==y then x,y=h[1],h[2] old=nil end
  end
  intent[pid]={x,y,d}
  -- A scripted turn at its original coordinates must not walk back off the corrected seat.
  if old and who and old[1]==x and old[2]==y then who[4]=d DrawSMap() ShowScreen() return end
  if pid~=375 then
   local used=occupied({[pid]=true})
   local service=SHOP[bg()] if service then used[#used+1]={service[1],service[2]} end
   local best,chosen
   for _,s in ipairs(ROWS[bg()]) do
    if free(s[1],s[2],used) then
     local cost=dist(x,y,s[1],s[2])
     if not best or cost<best then best,chosen=cost,s end
    end
   end
   if chosen then x,y,d=chosen[1],chosen[2],chosen[3] end
  end
  exact=true
  if h then
   local _,fx,fy=SnrPlan(h[1],h[2],x,y,pid)
   move(pid,x,y,d,exact)
   local w=current(pid)
   if w and fx then w[2]=fx w[3]=fy if d then w[4]=d end end
   DrawSMap() ShowScreen()
   return
  end
 end
 return move(pid,x,y,d,exact)
end
-- ko QA 11-04: 좌석표대로 앉히기 (patch_좌석표배치.py)
local KEEPGROUP=true
local function finish(pid,x,y,d)
 local w=current(pid)
 if w and not (rawget(_G,"koRouteFailed") and koRouteFailed(pid)) then w[2]=x w[3]=y if d then w[4]=d end end
 DrawSMap() ShowScreen()
end
local function seatedNow(who)
 for _,s in ipairs(ROWS[bg()]) do
  if math.abs(who[2]-s[1])<.01 and math.abs(who[3]-s[2])<.01 then return s end
 end
end
-- 이 장면만 좌석 줄 전체를 옮긴다 (다음 장면에서 원래대로)
function SnrSeatOffset(dx,dy)
 context()
 local b=bg()
 local base=ROWS[b]
 local t={}
 for i,r in ipairs(base) do t[i]={r[1]+dx,r[2]+dy,r[3],r[4],r[5]} end
 rowsBack={b,base}
 ROWS[b]=t
end
function SnrSeat(pid,x,y,d,force)
 context()
 if not isCity() then return move(pid,x,y,d) end
 local who=current(pid)
 if not who then SnrArrive(pid,x,y,d) who=current(pid) end
 local h=held[pid]
 if h then
  held[pid]=nil visitors[pid]=nil
  move(pid,h[1],h[2],h[3],true)
  return finish(pid,h[1],h[2],h[3])
 end
 if visitors[pid] and KEEPGROUP and not force then
  who[4]=visitors[pid][3]
  DrawSMap() ShowScreen()
  return
 end
 if visitors[pid] then visitors[pid]=nil
 elseif seatedNow(who) then
  who[4]=seatedNow(who)[3]   -- 방향도 좌석표대로
  DrawSMap() ShowScreen()
  return
 end
 local s=plan({{pid,x,y,d}},bg(),occupied({[pid]=true}),false)[1]
 move(pid,s[1],s[2],s[3],true)
 finish(pid,s[1],s[2],s[3])
end
function SnrHost(pid,x,y,d)
 context()
 if not isCity() then return move(pid,x,y,d) end
 local who=current(pid)
 local hs
 for _,s in ipairs(ROWS[bg()]) do if s[4]==0 then hs=s end end
 if not who then
  local D=rawget(_G,"SnrDoors") D=D and D[bg()]
  add(pid,D and D[3] or hs[1],D and D[4] or hs[2],0)
  who=current(pid)
 end
 for _,u in ipairs(JY.Smap) do
  if u[1]~=pid and math.abs(u[2]-hs[1])<.01 and math.abs(u[3]-hs[2])<.01 then return SnrSeat(pid,x,y,d) end
 end
 held[pid]=nil visitors[pid]=nil
 move(pid,hs[1],hs[2],hs[3],true)
 finish(pid,hs[1],hs[2],hs[3])
end
function SnrReportTo(pid,x,y,d)
 context()
 local c=isCity() and PROFILES[bg()].report_center
 if not c then return move(pid,x,y,d) end
 local who=current(pid)
 if not who then SnrArrive(pid,x,y,d,true) who=current(pid) end
 if not visitors[pid] and not held[pid] then
  local s=seatedNow(who)
  if s then held[pid]={s[1],s[2],s[3]} end
 end
 local all,skip={},{}
 for _,u in ipairs(JY.Smap) do if visitors[u[1]] and u[1]~=pid then all[#all+1]={u[1],u[2],u[3],u[4]} skip[u[1]]=true end end
 all[#all+1]={pid,x,y,d} skip[pid]=true
 if #all>6 then return SnrSeat(pid,x,y,d) end
 local slots
 if #all==1 then slots={{c[1],c[2],c[3]}} else slots=reportSlots(all,bg(),occupied(skip)) end
 if not slots then return SnrSeat(pid,x,y,d) end
 slots=koBestSlots(all,slots)
 for i,p in ipairs(all) do visitors[p[1]]=slots[i] end
 local T={}
 for i,p in ipairs(all) do
  local s=slots[i]
  if p[1]~=pid then
   local w=current(p[1])
   if w and (math.abs(w[2]-s[1])>.01 or math.abs(w[3]-s[2])>.01) then T[#T+1]={p[1],s} end
  end
 end
 T[#T+1]={pid,slots[#all]}
 koMoveTogether(T)
end
local decPerson=DecPerson
function DecPerson(pid,...)
 visitors[pid]=nil
 held[pid]=nil
 return decPerson(pid,...)
end
local draw=DrawSMap
local koGliding=false
local function koGlide(...)
 if not isCity() or koGliding then return end
 if not koDrawn or koDrawn.ref~=JY.Smap then koDrawn={ref=JY.Smap,at={}} end
 local at,J,n=koDrawn.at,{},0
 for _,u in ipairs(JY.Smap) do
  local p=at[u[1]]
  if p then
   local dx,dy=u[2]-p[1],u[3]-p[2]
   local ax,ay=math.abs(dx),math.abs(dy)
   if (ax>.6 or ay>.3) and ax<=5 and ay<=3 then
    local steps=math.ceil(math.max(ax/.4,ay/.2))
    if steps>n then n=steps end
    local face=u[4]
    if ax>.6 or ay>.3 then
     if dy<0 or (dy==0 and dx>0) then face=dx>=0 and 0 or 2 else face=dx>=0 and 3 or 1 end
    end
    J[#J+1]={u,p[1],p[2],u[2],u[3],u[4],u[5],dx,dy,face}
   end
  end
 end
 if n>0 then
  koGliding=true
  for k=1,n-1 do
   for _,g in ipairs(J) do local u=g[1] u[2]=g[2]+g[8]*k/n u[3]=g[3]+g[9]*k/n u[4]=g[10] u[5]=1 end
   JY.ReFreshTime=lib.GetTime()
   draw(...)
   ReFresh(1.25)
  end
  local hook=rawget(_G,"koGlideHook")
  for _,g in ipairs(J) do local u=g[1] u[2]=g[4] u[3]=g[5] u[4]=g[6] u[5]=g[7] if hook then hook(u[1],g[2],g[3],g[4],g[5]) end end
  koGliding=false
 end
 for _,u in ipairs(JY.Smap) do at[u[1]]={u[2],u[3]} end
end
function DrawSMap(...)
 koGlide(...)
 local moving=false
 for _,u in ipairs(JY.Smap) do if (u[5] or 0)>0 then moving=true break end end
 if isCity() and not moving then
  table.sort(JY.Smap,function(a,b)
   if a[3]~=b[3] then return a[3]<b[3] end
   if a[2]~=b[2] then return a[2]<b[2] end
   return a[1]<b[1]
  end)
 end
 return draw(...)
end
